css:
/* five declared ingredients, not four: the grid takes a fifth column rather than
   leaving an empty cell in the last row */
@media(min-width:800px){.ingr__grid{grid-template-columns:repeat(5,1fr)}}
@media(max-width:799px){.ingr__grid .ing:nth-child(5){grid-column:1/-1}.ingr__grid .ing:nth-child(5) img{aspect-ratio:2.2}}
